function.arguments:
{"script": "python3 << 'EOF'
import FreeCAD
doc = FreeCAD.open('/home/user/Precondition_Unnamed.FCStd')

# Check all properties of objects
for obj in doc.Objects:
    print(f"\n=== {obj.Name} ({obj.TypeId}) ===")
    for prop in obj.PropertiesList:
        try:
            val = getattr(obj, prop)
            print(f"  {prop}: {val}")
        except Exception as e:
            print(f"  {prop}: <error reading: {e}>")

# Check document properties
print("\n=== Document Properties ===")
for prop in doc.PropertiesList:
    try:
        val = getattr(doc, prop)
        print(f"  {prop}: {val}")
    except Exception as e:
        print(f"  {prop}: <error: {e}>")
EOF"}
